'use strict';
Object.assign(labels,{paneles:'Paneles del negocio',utilidad:'Utilidad · Superadministrador',importar:'Importar Charles'});
const executiveState={preview:null,imports:[],history:null,historyId:'',collection:'recentTransactions',page:0};
const privateReports=['general','finanzas','margen','productos','periodos','balance','adquisiciones','tendencia'];
reportKinds.operaciones='Resumen comercial';
function executiveFilters(){return `<div class="card"><div class="card-body row">${input('Desde','exec-start',appState.start,'date','required')+input('Hasta','exec-end',appState.end,'date','required')+pButton('Consultar','executive-apply','primary')+pButton('Este mes','executive-month')+pButton('Histórico','executive-all')}</div></div>`;}
function executiveView(privatePanel=false){return heading(privatePanel?'La utilidad, con todas sus cuentas.':'Tu negocio, desde cada ángulo.',privatePanel?'Acceso exclusivo del superadministrador. Ventas reconocidas − costo histórico − gastos operativos.':'Ventas, inventario, clientes y cobros en un solo lugar.',isSuper()?button(privatePanel?'Paneles del negocio':'Panel de utilidad','goto-'+(privatePanel?'paneles':'utilidad')):'')+executiveFilters()+'<div id="executive-content" aria-live="polite"><section class="card card-body">Consultando operaciones…</section></div>';}
function executiveBars(title,rows,format=money){const max=Math.max(1,...rows.map(r=>Math.abs(r.value)));return `<section class="card"><div class="card-head"><h2>${esc(title)}</h2></div><div class="card-body">${rows.length?rows.map(r=>`<div class="progress-row"><div class="row between"><span>${esc(r.name)}</span><strong>${esc(format(r.value))}</strong></div><div class="bar"><span style="width:${Math.abs(r.value)/max*100}%;${r.value<0?'background:#b45151':''}"></span></div></div>`).join(''):empty('Sin operaciones en este periodo','Selecciona otro periodo para consultar tus datos.')}</div></section>`;}
async function loadExecutive(){const target=document.querySelector('#executive-content');if(!target)return;try{const privatePanel=appState.route==='utilidad',r=await api('/api/executive?'+new URLSearchParams({panel:privatePanel?'utilidad':'negocio',start:appState.start,end:appState.end}));if(!target.isConnected)return;const a=r.summary;let content=`<div class="kpis">${kpi('Ventas reconocidas',money(a.revenue),a.transactions+' operaciones',true)+kpi('Ticket promedio',money(a.ticket),'Venta neta, sin impuestos')+kpi('Referencias activas',a.references,a.lowStock+' con stock bajo')+kpi('Peso disponible',grams(a.grams),'Excluye accesorios sin gramaje')}</div>`;
 if(privatePanel){const p=r.profit,i=r.inventory;content+=`<div class="kpis">${kpi('Utilidad bruta',money(p.grossProfit),'Ventas netas − costo de ventas')+kpi('Gastos operativos',money(p.expenses),'Incluye correcciones y anulaciones')+kpi('Utilidad operativa',money(p.operatingProfit),'No equivale al efectivo disponible',true)+kpi('Margen operativo',p.netMargin.toFixed(2)+' %','Sobre ventas netas reconocidas')}</div><div class="grid-equal">${executiveBars('Ventas, costos y resultado',[{name:'Ventas netas',value:p.netSales},{name:'Costo histórico de ventas',value:p.cost},{name:'Gastos operativos',value:p.expenses},{name:'Utilidad operativa',value:p.operatingProfit}])+executiveBars('Utilidad operativa mensual',r.months.map(m=>({name:m.month,value:m.profit})))}</div><section class="card"><div class="card-head"><h2>Estado mensual de resultados</h2>${pButton('CSV mensual','executive-export')}</div>${table(['Mes','Ventas COP','Costo COP','Gastos COP','Utilidad bruta COP','Utilidad operativa COP','Margen %'],r.months.map(m=>`<tr><td>${esc(m.month)}</td>${[m.revenue,m.cost,m.expenses,m.gross,m.profit].map(n=>'<td class="num">'+money(n)+'</td>').join('')}<td class="num">${m.margin.toFixed(2)} %</td></tr>`))}</section><div class="kpis">${kpi('Inventario al costo',money(i.cost),'Existencias activas actuales')+kpi('Inventario a precio de venta',money(i.retail),'Con las tarifas vigentes')+kpi('Utilidad potencial',money(i.potential),'Proyección del stock; aún no realizada')+kpi('Costo ponderado del metal',money(i.averagePerGram)+' / g','Excluye extras sin peso')}</div><section class="card"><div class="card-head"><h2>Productos que aportan al resultado</h2></div>${table(['Producto','Ventas COP','Costo COP','Utilidad COP','Margen %'],r.top.map(p=>`<tr><td>${esc(p.name)}</td><td class="num">${money(p.revenue)}</td><td class="num">${money(p.cost)}</td><td class="num">${money(p.profit)}</td><td class="num">${p.margin.toFixed(2)} %</td></tr>`))}</section><div class="info-strip">Las compras forman inventario; su costo se reconoce al vender. Los abonos de crédito cobran una venta previa. Los separes se reconocen al entregar. El resultado operativo no incluye gastos financieros o impuestos sobre la renta que no estén registrados. Las migraciones completas incorporan el historial reconocido; las importaciones iniciales antiguas conservan su archivo separado.</div>`;executiveState.profit=r;
 }else content+=`<div class="kpis">${kpi('Clientes activos',a.customers)+kpi('Proveedores activos',a.suppliers)+kpi('Servicios pendientes',a.services)+kpi('Referencias por reponer',a.lowStock)}</div><div class="grid-equal">${executiveBars('Ventas por categoría',r.categories)+executiveBars('Cobros por medio de pago',r.payments)}</div><section class="card"><div class="card-head"><h2>Desempeño por vendedor</h2></div>${table(['Vendedor','Ventas netas COP','Operaciones','Ticket promedio COP'],r.sellers.map(s=>`<tr><td>${esc(s.name)}</td><td class="num">${money(s.revenue)}</td><td class="num">${s.transactions}</td><td class="num">${money(s.transactions?s.revenue/s.transactions:0)}</td></tr>`))}</section><div class="info-strip">Los cobros se agrupan por fecha de pago e incluyen abonos: pueden diferir de las ventas reconocidas del periodo.</div>`;
 target.innerHTML=content;
 }catch(e){if(target.isConnected)target.innerHTML=empty('No pudimos consultar el panel',e.message);}}
function importView(){return heading('Importar base de datos de Charles','Importación inicial desde MongoDB o JSON · acceso exclusivo del superadministrador.')+`<div class="info-strip import-scope"><strong>Importación inicial · alcance parcial.</strong> Puedes incorporar catálogo, clientes, proveedores, activos y saldos pendientes como apertura. El historial antiguo se conserva para consulta: no alimenta los dashboards ni la utilidad histórica. Requiere una base de Áurea sin datos operativos; no mezcla ni reemplaza registros. Se conserva tu cuenta y el nombre Áurea.</div><section class="card card-body" aria-label="Pendientes de la migración"><h2>Qué falta para una migración completa</h2><p>Conciliar el historial de ventas, compras y abonos, los costos históricos, caja y cuentas bancarias. Los usuarios, contraseñas y perfiles no se importan.</p><p>La importación inicial se probó con datos ficticios. Antes de usar datos reales, hay que validar la conexión a tu MongoDB y revisar sus saldos y errores en la vista previa.</p></section><div class="grid-equal import-grid"><section class="card"><div class="card-head"><h2>Conectar con MongoDB</h2></div><div class="card-body">${pForm('charles-mongo-form',input('URI de MongoDB · usuario de lectura','uri','','password','required autocomplete="off" spellcheck="false" placeholder="mongodb+srv://…"')+input('Base de datos','database','charlesjoyas_pos','text','required')+input('Colección','collection','nexusdatas','text','required')+'<p class="muted">La conexión se usa únicamente para consultar main_store. La URI no se guarda. La vista previa vence después de 10 minutos.</p>','Leer y preparar vista previa')}</div></section><section class="card"><div class="card-head"><h2>También desde una copia JSON</h2></div><div class="card-body">${pForm('charles-json-form',input('Exportación JSON de Charles','file','','file','required accept=".json,application/json"')+'<p class="muted">Acepta el estado de Charles o un documento con content. No importa contraseñas ni cuentas de usuario.</p>','Revisar archivo')}</div></section></div><div id="charles-preview"></div><section class="card"><div class="card-head"><h2>Importaciones e historial original</h2></div><div class="card-body" id="charles-imports">Consultando…</div></section><div id="charles-history"></div>`;}
function renderImportPreview(){const target=document.querySelector('#charles-preview'),p=executiveState.preview;if(!target||!p)return;target.innerHTML=`<section class="card"><div class="card-head"><h2>Revisa antes de importar</h2></div><div class="card-body"><p>Huella del contenido: <code>${esc(p.digest.slice(0,20))}…</code></p><div class="kpis">${kpi('Productos',p.counts.products||0)+kpi('Inventario al costo',money(p.totals.stockCost))+kpi('Cartera inicial',money(p.totals.receivables))+kpi('Deuda a proveedores',money(p.totals.payables))}</div>${table(['Colección de origen','Registros'],Object.entries(p.counts).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v}</td></tr>`))}<h3>Muestra del catálogo convertido</h3>${table(['SKU','Nombre','Medida','Stock','Costo COP','Precio COP'],p.samples.map(s=>`<tr><td>${esc(s.sku)}</td><td>${esc(s.name)}</td><td>${esc(s.measureType)}</td><td>${s.stock}</td><td class="num">${money(s.cost)}</td><td class="num">${money(s.price)}</td></tr>`))}<ul>${p.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')}</ul>${p.errors.length?'<div class="field-error"><strong>Importación bloqueada</strong><ul>'+p.errors.map(e=>'<li>'+esc(e)+'</li>').join('')+'</ul></div>':pForm('charles-confirm-form',input('Escribe IMPORTAR CHARLES para incorporar estos datos','confirmation','','text','required autocomplete="off"')+'<p class="muted">Se creará un respaldo de Áurea antes de aplicar la importación. No reemplaza información existente.</p>','Importar datos revisados')}${pButton('Descartar vista previa','import-cancel','text')}</div></section>`.replaceAll('Datos guardados en Áurea','Vista previa · datos todavía sin importar');}
async function loadImports(){const target=document.querySelector('#charles-imports');if(!target)return;try{const r=await api('/api/import/list');if(!target.isConnected)return;executiveState.imports=r.imports;target.innerHTML=r.imports.length?r.imports.map(i=>`<div class="list-item"><div class="list-text"><strong>${fmtDate(i.createdAt)}</strong><small>${i.summary.counts.products||0} productos · ${esc(i.digest.slice(0,14))} · respaldo ${esc(i.summary.backup)}</small></div>${pButton('Consultar historial','import-history-'+i.id)}</div>`).join(''):'Aún no has importado datos de Charles.';}catch(e){target.textContent=e.message;}}
const historyNames={recentTransactions:'Ventas originales',purchases:'Compras originales',expenses:'Gastos originales',abonosVentas:'Abonos de ventas',abonosCompras:'Abonos de compras',cashShiftsHistory:'Cierres de caja',customerCredits:'Créditos de clientes',supplierCredits:'Créditos de proveedores'};
async function loadImportedHistory(){const target=document.querySelector('#charles-history');if(!target)return;target.innerHTML='<section class="card card-body">Consultando historial…</section>';try{const r=await api('/api/import/history?'+new URLSearchParams({id:executiveState.historyId,collection:executiveState.collection,page:executiveState.page}));if(!target.isConnected)return;target.innerHTML=`<section class="card"><div class="card-head"><h2>Archivo original de Charles · solo consulta</h2></div><div class="card-body row">${select('Historial','charles-collection',Object.entries(historyNames),executiveState.collection)+pButton('Consultar','import-history-load')}</div><p class="card-body muted">${r.total} registros. Estos documentos no se contabilizan como nuevas ventas o pagos en Áurea.</p>${table(['Registro','Documento original'],r.rows.map(row=>`<tr><td>${esc(row.id||'Sin ID')}<small>${esc(row.date||'')}</small></td><td><details><summary>Ver documento</summary><pre class="draft-preview">${esc(JSON.stringify(row,null,2))}</pre></details></td></tr>`))}<div class="card-body row">${r.page?pButton('Anterior','import-history-prev'):''}<span>Página ${r.page+1} de ${Math.max(1,Math.ceil(r.total/50))}</span>${(r.page+1)*50<r.total?pButton('Siguiente','import-history-next'):''}</div></section>`;}catch(e){target.innerHTML=empty('No pudimos cargar el historial',e.message);}}
Object.assign(extraUI.views,{paneles:()=>executiveView(false),utilidad:()=>executiveView(true),importar:importView});
const executiveDecorate=extraUI.decorate;
extraUI.decorate=function(){executiveDecorate();const nav=document.querySelector('.sidebar nav');if(nav){nav.insertAdjacentHTML('beforeend',(allowed('inicio')?`<a href="#paneles" class="nav-item ${appState.route==='paneles'?'active':''}">${icon('chart')}Paneles del negocio</a>`:'')+(isSuper()?`<a href="#utilidad" class="nav-item ${appState.route==='utilidad'?'active':''}">${icon('lock')}Panel de utilidad</a><a href="#importar" class="nav-item ${appState.route==='importar'?'active':''}">${icon('download')}Importar Charles</a>`:''));}if(['paneles','utilidad'].includes(appState.route))loadExecutive();if(appState.route==='importar'){loadImports();renderImportPreview();}if(appState.route==='inicio')document.querySelector('.page-heading .actions')?.insertAdjacentHTML('beforeend',allowed('inicio')?button('Ver paneles','goto-paneles'):'');};
const executiveAction=extraUI.action;
extraUI.action=async function(a,t){if(a==='x-executive-apply'||a==='x-executive-month'||a==='x-executive-all'){if(a==='x-executive-apply'){appState.start=document.querySelector('[name=exec-start]').value;appState.end=document.querySelector('[name=exec-end]').value;}else{appState.start=a==='x-executive-month'?appState.today.slice(0,7)+'-01':'0001-01-01';appState.end=appState.today;}render();return;}if(a==='x-executive-export'){const r=await api('/api/executive?'+new URLSearchParams({panel:'utilidad',start:appState.start,end:appState.end})),rows=[['Mes','Ventas COP','Costo COP','Gastos COP','Utilidad bruta COP','Utilidad operativa COP','Margen %'],...r.months.map(m=>[m.month,m.revenue,m.cost,m.expenses,m.gross,m.profit,m.margin])];executiveDownload(new Blob(['\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'Aurea-utilidad-mensual.csv');return;}if(a==='x-import-cancel'){if(executiveState.preview)await api('/api/import/cancel',{method:'POST',body:JSON.stringify({previewId:executiveState.preview.previewId})});executiveState.preview=null;render();return;}if(a.startsWith('x-import-history-')){const mode=a.slice(17);if(mode==='load'){executiveState.collection=document.querySelector('[name=charles-collection]').value;executiveState.page=0;}else if(mode==='prev')executiveState.page=Math.max(0,executiveState.page-1);else if(mode==='next')executiveState.page++;else{executiveState.historyId=mode;executiveState.page=0;}await loadImportedHistory();return;}return executiveAction(a,t);};
const executiveSubmit=extraUI.submit;
extraUI.submit=async function(form,v){if(['charles-mongo-form','charles-json-form'].includes(form.id)){let payload;if(form.id==='charles-mongo-form'){payload={source:'mongo',uri:v.uri,database:v.database,collection:v.collection};}else{const file=form.elements.file.files[0];if(!file||file.size>20*1024*1024)throw Error('Selecciona un archivo JSON de hasta 20 MB.');let doc;try{doc=JSON.parse(await file.text());if(Array.isArray(doc)&&doc.length===1)doc=doc[0];}catch{throw Error('El archivo no contiene JSON válido.');}payload={source:'json',data:doc.content||doc};}try{executiveState.preview=await api('/api/import/preview',{method:'POST',body:JSON.stringify(payload)});}finally{if(form.elements.uri)form.elements.uri.value='';}renderImportPreview();return null;}if(form.id==='charles-confirm-form'){await api('/api/import/confirm',{method:'POST',body:JSON.stringify({previewId:executiveState.preview?.previewId,confirmation:v.confirmation})});executiveState.preview=null;await load();render();toast('Importación guardada. Revisa el historial y concilia caja y bancos antes de operar.');return null;}return executiveSubmit(form,v);};
const executiveReportFilters=reportFilters;
reportFilters=function(){const html=executiveReportFilters();if(isSuper())return html;const template=document.createElement('template');template.innerHTML=html;template.content.querySelectorAll('[name=parity-kind] option').forEach(o=>{if(privateReports.includes(o.value))o.remove();});return template.innerHTML;};
const executiveReportsView=detailedReportsView;
detailedReportsView=function(){if(!isSuper()&&privateReports.includes(parityState.kind))parityState.kind='operaciones';return executiveReportsView();};
extraUI.views.reportes=detailedReportsView;extraUI.views.informes=detailedReportsView;

function executiveDownload(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Exportación generada.');}
